"""Offline annotated evidence for parser counts and accepted-input state."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA012,0xA013,'data','Contatore temporaneo del parser: inizialmente FF'),(0xA019,0xA01A,'data','Contatore cumulativo delle righe e MORE'),(0xAAB2,0xAABD,'code','Inizio parsing: azzera contatore e stato ALL/BUT'),(0xACCC,0xAD72,'code','Coordinazioni, esclusioni e ripristino del contatore nel backtracking'),(0xB01C,0xB049,'code','ALL e BUT: nodo extra e stato della selezione'),(0xB0FD,0xB16D,'code','THAT, HE, IT/THEY: riallocazione e conteggi diversi'),(0xC2CA,0xC2DA,'code','MORE a quota quindici: attesa, FF e incremento modulo 256'),(0xD6C1,0xD6CE,'code','Input accettato: azzera sempre il flag transitorio di @'),(0xD714,0xD715,'data','Flag transitorio di riuso dei token nell’editor'),(0xD719,0xD726,'code','Tokenizzazione: azzera MORE e consulta il flag di riuso'),(0xD99E,0xD9AC,'code','Tasto @: flag temporaneo, ignorato durante una precisazione')]
regions += [(0xBA1C,0xBA20,'data','Deduzioni di Lestrade: riconosciute, non provate e ultimo fatto'),(0xBB67,0xBC46,'code','Verifica delle frasi: contatori e puntatore dell’ultimo fatto riconosciuto'),(0xBC74,0xBCC9,'code','Scansione delle ipotesi: primo fatto completo e ultimo incompleto')]
notes={0xA012:'Byte FF del payload iniziale. AAB6 lo azzera solo quando inizia il parser; un errore lessicale precedente lo conserva.',0xA019:'Stato già ricostruito dal renderer e ora esposto al generatore: non è il numero di righe del singolo comando.',0xD714:'Il tasto @ scrive 1 a D9A7, ma D6C8 ripristina 0 prima del preflight lessicale e dei turni NPC. Il profilo della pagina salva soltanto input completati.',0xAAB6:'Nuovo ingresso AAB2: contatore zero anche per citazioni vuote e per i tentativi che falliscono nella sintassi.',0xACE8:'Salva il conteggio prima di proseguire speculativamente oltre la congiunzione.',0xACF5:'Con BUT attivo, marca il nodo esclusione; il separatore A0 non deve contare questo nodo.',0xAD3D:'Ripristina il contatore salvato quando il nuovo verbo va rinviato al ciclo successivo. Le allocazioni speculative restano distinte dal conteggio.',0xAD57:'A01A=2 e separatore A0: salta l’incremento. La chiusura finale invece conta anche l’esclusione.',0xAD66:'Incremento a otto bit: conta il percorso di parsing completato, non semplicemente i nodi allocati.',0xB026:'BUT passa a stato 2 e crea un nodo senza passare per l’incremento AD66 del nodo principale.',0xB03F:'ALL imposta stato 1. Un BUT senza nome è accettato dal parser originale: gruppo nominale vuoto, payload zero.',0xB11B:'THAT senza separatore crea un ulteriore nodo e incrementa il contatore.',0xB147:'HE senza separatore alloca un nodo ma NON incrementa A012 come THAT: la chiusura finale lo porta a 1.',0xB163:'IT/THEY seguono lo stesso percorso di riallocazione senza incremento supplementare.',0xC2D1:'La quindicesima quota cumulativa attende MORE prima del CR successivo.',0xC2D4:'Il successivo INC A trasforma FF in zero dopo la conferma.',0xD6C8:'Reset del flag anche dopo @: ogni ingresso valido torna a zero prima del preflight. Non trasformare 1 in un attributo persistente del comando.',0xD71A:'La nuova tokenizzazione azzera il contatore MORE. Gli errori lessicali fermati prima di questo ingresso non lo fanno.',0xD9A7:'Scrittura transitoria a uno; il successivo ritorno attraverso D6C8 la annulla.'}
notes.update({0xBA1C:'Due contatori a un byte e un puntatore little-endian. Inizialmente zero; restano osservabili dai successivi sorteggi.',0xBB67:'Nuova verifica: azzera i contatori di riconoscimento e non provato; conserva il vecchio puntatore finché non riconosce un fatto.',0xBB7B:'Incrementa il numero di frasi riconosciute modulo 256.',0xBC31:'Registra il fatto riconosciuto prima di valutarne la prova. Non è necessariamente l’ultimo fatto non provato.',0xBC3C:'Imposta il flag non provato a uno: non conta quanti fatti mancano.',0xBC8C:'Scansione senza ipotesi completa: conserva l’ultimo fatto incompleto.',0xBCB9:'Con ipotesi complete seleziona la prima; questa scansione non azzera i contatori della verifica precedente.'})
fields={0xA012:[['A012','1','Contatore a 8 bit; FF iniziale, zero a inizio AAB2, incrementi AD66/B11B e ripristino AD3D']],0xA019:[['A019','1','Quota cumulativa: reset D71A; CR e MORE C2CA–C2D9']],0xD714:[['D714','1','Flag temporaneo: set da @, reset quando l’editor consegna l’input']]}
fields[0xBA1C]=[['BA1C','1','Numero di frasi riconosciute, modulo 256'],['BA1D','1','Flag: almeno un fatto riconosciuto non è provato'],['BA1E','2','Ultimo fatto riconosciuto o selezionato dalla scansione delle ipotesi']]
lines=['; Codice e dati distinti, verificati contro il payload. Nessun opcode eseguito dal runtime JS.'];total=count=0
for a,b,kind,label in sorted(regions):
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/parser-counter';root.mkdir(exist_ok=True)
(root/'parser-counter.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=121 if k=='data'else 86,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
